-- GetContact initial schema.
-- All primary keys are generated by the application (UUIDv4) so the schema does
-- not depend on server-side extensions. pg_trgm powers fast fuzzy search.

CREATE EXTENSION IF NOT EXISTS pg_trgm;

CREATE TABLE IF NOT EXISTS users (
    id            UUID PRIMARY KEY,
    phone         VARCHAR(20)  NOT NULL UNIQUE,
    email         VARCHAR(254),
    password_hash TEXT         NOT NULL,
    display_name  VARCHAR(64)  NOT NULL,
    role          VARCHAR(16)  NOT NULL DEFAULT 'user' CHECK (role IN ('user', 'admin')),
    is_blocked    BOOLEAN      NOT NULL DEFAULT FALSE,
    created_at    TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at    TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);

CREATE UNIQUE INDEX IF NOT EXISTS ux_users_email_lower
    ON users (LOWER(email)) WHERE email IS NOT NULL AND email <> '';
CREATE INDEX IF NOT EXISTS ix_users_created_at ON users (created_at DESC);
CREATE INDEX IF NOT EXISTS ix_users_is_blocked ON users (is_blocked) WHERE is_blocked;
CREATE INDEX IF NOT EXISTS ix_users_display_name_trgm
    ON users USING GIN (display_name gin_trgm_ops);

CREATE TABLE IF NOT EXISTS contacts (
    id          UUID PRIMARY KEY,
    owner_id    UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    phone       VARCHAR(20) NOT NULL,
    name        VARCHAR(128) NOT NULL,
    email       VARCHAR(254),
    note        VARCHAR(1000),
    is_favorite BOOLEAN     NOT NULL DEFAULT FALSE,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT ux_contacts_owner_phone UNIQUE (owner_id, phone)
);

CREATE INDEX IF NOT EXISTS ix_contacts_owner_created
    ON contacts (owner_id, created_at DESC);
CREATE INDEX IF NOT EXISTS ix_contacts_owner_name
    ON contacts (owner_id, LOWER(name));
CREATE INDEX IF NOT EXISTS ix_contacts_name_trgm
    ON contacts USING GIN (name gin_trgm_ops);
CREATE INDEX IF NOT EXISTS ix_contacts_owner_favorite
    ON contacts (owner_id) WHERE is_favorite;

CREATE TABLE IF NOT EXISTS numbers (
    phone         VARCHAR(20) PRIMARY KEY,
    name          VARCHAR(128),
    carrier       VARCHAR(64),
    country       VARCHAR(64),
    spam_score    SMALLINT    NOT NULL DEFAULT 0 CHECK (spam_score BETWEEN 0 AND 100),
    reports_count BIGINT      NOT NULL DEFAULT 0,
    lookups_count BIGINT      NOT NULL DEFAULT 0,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS ix_numbers_spam_score
    ON numbers (spam_score DESC, reports_count DESC);
CREATE INDEX IF NOT EXISTS ix_numbers_lookups
    ON numbers (lookups_count DESC);
CREATE INDEX IF NOT EXISTS ix_numbers_name_trgm
    ON numbers USING GIN (name gin_trgm_ops);

CREATE TABLE IF NOT EXISTS tags (
    id         UUID PRIMARY KEY,
    phone      VARCHAR(20) NOT NULL REFERENCES numbers (phone) ON DELETE CASCADE,
    tag        VARCHAR(32) NOT NULL,
    weight     INTEGER     NOT NULL DEFAULT 1 CHECK (weight > 0),
    created_by UUID        REFERENCES users (id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT ux_tags_phone_tag UNIQUE (phone, tag)
);

CREATE INDEX IF NOT EXISTS ix_tags_phone_weight ON tags (phone, weight DESC);
CREATE INDEX IF NOT EXISTS ix_tags_tag ON tags (tag);
CREATE INDEX IF NOT EXISTS ix_tags_created_by ON tags (created_by) WHERE created_by IS NOT NULL;

CREATE TABLE IF NOT EXISTS spam_reports (
    id          UUID PRIMARY KEY,
    phone       VARCHAR(20) NOT NULL REFERENCES numbers (phone) ON DELETE CASCADE,
    reporter_id UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    category    VARCHAR(32) NOT NULL CHECK (category IN ('fraud', 'scam', 'telemarketing', 'robocall', 'spam', 'other')),
    comment     VARCHAR(500),
    created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    -- one active report per user per number prevents trivial score manipulation
    CONSTRAINT ux_spam_reports_phone_reporter UNIQUE (phone, reporter_id)
);

CREATE INDEX IF NOT EXISTS ix_spam_reports_phone_created
    ON spam_reports (phone, created_at DESC);
CREATE INDEX IF NOT EXISTS ix_spam_reports_created_at
    ON spam_reports (created_at DESC);
CREATE INDEX IF NOT EXISTS ix_spam_reports_reporter
    ON spam_reports (reporter_id);

CREATE TABLE IF NOT EXISTS refresh_tokens (
    id         UUID PRIMARY KEY,
    user_id    UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    token_hash CHAR(64)    NOT NULL UNIQUE,
    user_agent VARCHAR(256),
    ip         VARCHAR(64),
    expires_at TIMESTAMPTZ NOT NULL,
    revoked_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS ix_refresh_tokens_user
    ON refresh_tokens (user_id) WHERE revoked_at IS NULL;
CREATE INDEX IF NOT EXISTS ix_refresh_tokens_expires
    ON refresh_tokens (expires_at) WHERE revoked_at IS NULL;

-- Worker-side idempotent event log (also useful as an audit trail).
CREATE TABLE IF NOT EXISTS audit_events (
    id           UUID PRIMARY KEY,
    topic        VARCHAR(128) NOT NULL,
    event_type   VARCHAR(64)  NOT NULL,
    aggregate_id VARCHAR(64)  NOT NULL,
    payload      JSONB        NOT NULL,
    occurred_at  TIMESTAMPTZ  NOT NULL,
    consumed_at  TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS ix_audit_events_type_time ON audit_events (event_type, consumed_at DESC);
CREATE INDEX IF NOT EXISTS ix_audit_events_aggregate ON audit_events (aggregate_id);

-- Keep updated_at accurate without application bookkeeping.
CREATE OR REPLACE FUNCTION set_updated_at() RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_users_updated_at ON users;
CREATE TRIGGER trg_users_updated_at BEFORE UPDATE ON users
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

DROP TRIGGER IF EXISTS trg_contacts_updated_at ON contacts;
CREATE TRIGGER trg_contacts_updated_at BEFORE UPDATE ON contacts
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

DROP TRIGGER IF EXISTS trg_numbers_updated_at ON numbers;
CREATE TRIGGER trg_numbers_updated_at BEFORE UPDATE ON numbers
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();
